input.command:
cd "C:/Users/rafal/AppData/Local/Temp/ajs-facts-hybrid-tool-pd8ZbI/workspace" && node ../tools/ajs-facts.mjs list filters --root . --json > ./f.json && node ../tools/ajs-facts.mjs list services --root . --json > ./s.json && node -e "
const fs=require('fs');
const C=JSON.parse(fs.readFileSync('./c.json','utf8'));
const F=JSON.parse(fs.readFileSync('./f.json','utf8'));
const S=JSON.parse(fs.readFileSync('./s.json','utf8'));
const ans={
 deadComponents: C.filter(c=>c.usedBy.length===0).map(c=>c.name),
 leafComponents: C.filter(c=>c.renders.length===0).map(c=>c.name),
 standardBearerElements: C.find(c=>c.name==='standardBearer').usedBy.filter(u=>u.kind==='template').length,
 unusedFilters: F.filter(f=>f.usedBy.length===0).map(f=>f.name),
 twinComponents: C.filter(c=>c.twin).map(c=>c.name),
 unusedServices: S.filter(s=>s.usedBy.length===0).map(s=>s.name)
};
fs.writeFileSync('./answers.json',JSON.stringify(ans,null,2));
console.log(JSON.stringify(ans,null,2));
" && rm ./c.json ./f.json ./s.json

